from src.malignant.literature import qualify_literature_candidate
def test_same_patient_without_cell_linkage_rejected(): assert qualify_literature_candidate()=='MALIGNANT_NOT_OBSERVABLE'
def test_same_sample_without_cell_linkage_rejected(): assert qualify_literature_candidate()=='MALIGNANT_NOT_OBSERVABLE'
def test_same_cluster_without_cell_linkage_rejected(): assert qualify_literature_candidate()=='MALIGNANT_NOT_OBSERVABLE'
def test_publication_only_partial(): assert qualify_literature_candidate(malignant_validated=True,public_mapping=False)=='MALIGNANT_PARTIAL'
def test_unsupported_cnv_partial(): assert qualify_literature_candidate(cnv_supported=True,reference_available=False)=='MALIGNANT_PARTIAL'
def test_genotype_without_barcode_partial(): assert qualify_literature_candidate(malignant_validated=True,public_mapping=False)=='MALIGNANT_PARTIAL'
def test_treatment_identity_rejected(): assert qualify_literature_candidate(same_cell=True,public_mapping=True,malignant_validated=True,treatment_used=True)=='MALIGNANT_NOT_OBSERVABLE'
def test_outcome_identity_rejected(): assert qualify_literature_candidate(same_cell=True,public_mapping=True,malignant_validated=True,outcome_used=True)=='MALIGNANT_NOT_OBSERVABLE'
def test_validated_same_cell_ground_truth(): assert qualify_literature_candidate(same_cell=True,public_mapping=True,malignant_validated=True,direct_ground_truth=True)=='MALIGNANT_GROUND_TRUTH'
def test_reproducible_cell_cnv_e4(): assert qualify_literature_candidate(same_cell=True,public_mapping=True,malignant_validated=True,cnv_supported=True,reference_available=True)=='MALIGNANT_REPRODUCIBLE_INFERENCE'
def test_cell_cnv_reference_requires_mapping(): assert qualify_literature_candidate(same_cell=True,public_mapping=True,malignant_validated=False,cnv_supported=True,reference_available=True)=='MALIGNANT_PARTIAL'
